&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Ganzheitliche Kundenberatung&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;für schlüsselfertige, mehrgeschossige Wohnbauprojekte – von der ersten qualifizierten Anfrage bis zur Vertragsunterzeichnung&lt;/span&gt;&amp;nbsp;&lt;br&gt;&lt;em&gt;&lt;span data-contrast=&quot;auto&quot;&gt;(keine Kaltakquise)&lt;/span&gt;&lt;/em&gt;&lt;/li&gt;
